const target = msg.metadata.target;

if (!target || !target.api_key || !target.client_specific.chatroom_name) {
    node.error("WaSOS not configured on this connection");
    return null;
}

msg.url = global.get("parat_bridge").base_urls.wasos
    + "/api/chat/messages/" + target.client_specific.chatroom_name;

msg.headers = {
    "x-api-key":    target.api_key,
    "Content-Type": "application/json"
};

return msg;

msg.topic = "response"

if (msg.statusCode == 200) {
    msg.result = true
} else {
    msg.result = false
}

return msg;
